import { screen } from './shared.js';
export function renderDownloads(missions,downloads){return screen('Загрузки и обновления',`<div class="download-summary"><strong>Полный автономный комплект</strong><span>${missions.length} миссий · версия 2026.09</span><button class="primary" data-action="download-all">Скачать все миссии</button></div><div class="download-list">${missions.map(m=>`<article><div><strong>${m.id}. ${m.title}</strong><span>${downloads[m.id]?.state==='downloading'?'Загружается…':'Скачана · '+m.version}</span></div><button data-action="download" data-mission="${m.id}">${downloads[m.id]?.state==='downloading'?'Отменить загрузку':'Обновить'}</button></article>`).join('')}</div>`);}
